SELECT GROUP_CONCAT(v ORDER BY v SEPARATOR ',' LIMIT 2) FROM t;

SELECT GROUP_CONCAT(DISTINCT v ORDER BY v DESC SEPARATOR '; ' LIMIT 2) FROM t;

SELECT GROUP_CONCAT(v ORDER BY v LIMIT 1, 2) FROM t;

SELECT GROUP_CONCAT(v ORDER BY v LIMIT 2 OFFSET 1) FROM t;

SELECT GROUP_CONCAT(v ORDER BY v LIMIT ?) FROM t;

-- A routine variable.
SELECT GROUP_CONCAT(v ORDER BY v LIMIT n OFFSET m) FROM t;
